const fs=require('node:fs');const B='D:/hypertower-recovery-20261026',W=B+'/walkthrough-work-20261101',D=W+'/simulation-p2';const high=JSON.parse(fs.readFileSync(D+'/long-horizons.json','utf8')),low=JSON.parse(fs.readFileSync(D+'/low-progress-and-route.json','utf8')),native=JSON.parse(fs.readFileSync(D+'/native-1day.json','utf8'));const roman=['','I','II','III','IV','V','VI','VII','VIII','IX','X','XI','XII','XIII','XIV','XV','XVI','XVII','XVIII','XIX','XX'];const names={'1day':'1 天','1week':'1 周','1month':'1 个月','1year':'1 年','10years':'10 年','100years':'100 年'},commas=s=>String(s).replace(/\B(?=(\d{3})+(?!\d))/g,','),table=high.rows.map(r=>'| '+names[r.label]+' | '+commas(r.round)+' | '+commas(r.roundsAdded)+' | '+commas(r.points)+' | '+roman[r.era]+' | '+r.currentRoundSeconds.toFixed(6)+' 秒 |').join('\n');
let md=`## P2 终盘后继续运行：一天、一周、一个月、一年、十年与一百年\n\n这里给出的未来进度来自隔离存档与当前原生事件内核，不把截图里预设的轮数当成运行结果，也没有调用群星纪的三轮拟合预测。主表使用玩家此前明确描述的历史高进度：225000次归一、6600万太一。它与首次完成XX的速度差距很大，后面同时给出低遗产对照和第一次XI→XX路线时间尺。\n\n### 两份起点，先把差别说清\n\n高进度起点是XX已完成、225000次归一、66000000太一、XI–XX共720星、十张经过验证的本纪元代表蓝图。XI代表质量1.4，XII–XX代表质量1.2；携带MA、natural、fixed，无挑战、无工坊规则，完整轮回自动化开启。为了把未来时间从同一点开始，基线当前轮已计时600秒，先执行一次正常归一，获得61太一，随后才计未来一天等时长。表中的“累计归一”包含这次起步归一。\n\n这些历史数字和720星是公开提供的初态，不是本次运行倒推出来的成绩。本次没有模拟最初的225000轮，也没有把人工解240题的现实耗时算进来。代表蓝图通过正常验证器产生，原生存档可重新导入；真实玩家存档没有被读取或覆盖。蓝图库固定保留十张代表，未在模拟中无限增加蓝图或自动补星。\n\n低进度起点从零太一、零归一建立。先按已经知道各题设计的条件，用原生事件积分走完XI→XX，手动按门槛关闭AC，并在需要时正常购买确定性执行；在XX封存MA、natural、fixed后才开始第一轮归一。720星与解题知识预先提供，主线推进时间实际计算，所以这是一份“已会解题的首轮研究路线”基准，不是完全新手从读规则到找答案的总耗时。\n\n### 历史高进度终盘：六个真实checkpoint\n\n一周按7天、一个月按30天、一年按365天计算。没有把“一个月”偷偷换成31天，也没有以现实闰年改变远期长度。每个checkpoint都保存了游戏原生HT5格式和SHA-256，末尾不到五轮的时间仍由原生内核积分到指定时长，不会把存档强行停在整轮结算点。\n\n| 继续时间 | 累计归一 | 相对225000轮增加 | 累计太一 | 当前所在纪元 | 当前轮已过 |\n| --- | ---: | ---: | ---: | --- | ---: |\n${table}\n\n当前纪元不是新的通关上限。例如一年后仍显示XVII，只说明精确到该时刻正在这一轮的XVII，不表示一年只能玩到XVII。累计轮数才记录之前完整归一过多少次。结束在XIV或XVI同理，应同时阅读轮数、当前纪元和当前轮时间。\n\n也不能把表中的增量直接套给刚通关玩家。主表起点的遗产倍率已经达到4000硬上限；只改变初态为零太一，即使使用同样的蓝图和自动化，第一天的结果也完全不同。表里的高速度来自已累积资本与明确策略，没有替代720星或当前纪元合法性。\n\n### 第一个整天另外完整跑了一遍，没有跳过任何轮\n\n为了检验周期批处理，先独立运行完整86400秒原生事件积分。它实际执行${commas(native.steps)}次原生步，墙钟耗时${native.wallSeconds.toFixed(3)}秒，得到累计归一${commas(native.round)}、太一${commas(native.points)}、当前${roman[native.era]}。这些离散结果与周期批处理的一天结果完全一致，档案、蓝图ID和工坊状态也一致。\n\n原生逐事件积分仍使用浮点数。完整一天的普通剩余时间反复相减，与把整周期合并相加，在末段相位出现约1.2微秒的舍入差；这对应约0.00005255研究坐标。英雄巨数是研究坐标的高阶派生显示，对极小输入误差可能放大，因此不能宣称两份巨数缓存逐位相同。原始对照报告保留了这些差异，轮数和太一点数使用整数，未以容差放宽。\n\n远期验证同样单独进行：把状态放到接近100年的完整周期位置，再额外用原生内核逐事件跑五轮，所得规范持久核心、轮数、太一点、蓝图ID、档案和规则时钟相同；绝对时钟浮点加法的差异约0.000113秒。这个误差属于时钟表达顺序，不能把它包装成所有字段逐bit一致。\n\n### 为什么这里能跳过完整五轮，并且与拟合不同\n\n当前源码的遗产倍率在4000封顶。6600万太一起点已处于封顶区，后面点数单调增加，倍率不会再因点数变化而改变。归一又用新的基础状态重建本轮：档案、代表蓝图、成就、界面设置和携带项继续保留，本轮资源、研究和阶段重新建立。本基线工坊没有规则，也不再提交新蓝图，所以没有会缓慢变化的规则时钟或蓝图ID。\n\n本轮元公理按归一计数模5轮换。自然和起步、研究加速、HighLife、三符号和确定性执行在五轮后回到同一种；携带natural和fixed还固定了部分起步条件。我们逐事件执行五轮，原生导入规范化后的全部持久核心在五轮前后确实相同；又继续执行多个周期验证相同哈希，不是从三次时长拟合一条直线。\n\n这份基线的单轮实际研究耗时为31.016728687112秒，五轮为155.083643435558秒。每一轮都小于结算使用的60秒下限，所以实际结算严格为floor(36000/60)+1=601太一。奖励的floor无需用平均速度近似，五轮就是3005太一。将完整五轮重复批处理时，累计轮数加5、太一点加3005、绝对时间加该周期时长，当前归一日志及最快轮回显示按同一规则更新。\n\n批处理不适用于任意存档。更换携带遗产、启用挑战、增加工坊规则、删除代表蓝图、降低初始遗产到未封顶区，都会改变输入条件，需要重新做原生积分和状态重复证明。群星纪的影子fit模式是另一个功能，本节没有调用它，也没有把它的预测值冒充这个证明。\n\n### 低遗产对照：第一次XX完成以后，一天与一周\n\n首轮XI→XX研究路线实跑${(low.firstRoute.stageSumSeconds/3600).toFixed(6)}小时，第一次归一获得${low.firstRoute.firstNormalizeEarned}太一。然后启用同样的完整轮回自动化，继续未来时间。以下两行均直接逐事件运行，没有周期批处理，也没有把高进度基线的31秒单轮套进来。\n\n| 首次XX之后继续 | 累计归一 | 太一 | 当前纪元 | 当前遗产倍率 | 原生步数 |\n| --- | ---: | ---: | --- | ---: | ---: |\n${low.rows.map(r=>'| '+names[r.label]+' | '+r.round+' | '+r.points+' | '+roman[r.era]+' | '+r.multiplier.toFixed(6)+' | '+commas(r.nativeSteps)+' |').join('\n')}\n\n这个对照说明，第一次归一后的加速要经过真实积累，不会直接跳到主表的历史高进度。首个整天已经完成若干次归一、又在新轮中途，并不意味着自动化出了问题。先核对太一与倍率在增加，再看每轮是否顺利经过XVIII宇宙和XIX关闭AC。\n\n若你没有720星、缺少可生产的代表，或者仍未安排AC关闭后的确定性执行，实际路线会更慢或停在硬条件处。本表已经假定这些设计知识存在，不能拿它保证任何新玩家24小时必到相同位置。\n\n### 第一次XI→XX的研究时间尺\n\n下面是本次重新运行的单条路线：零太一、零归一，每纪元72星已预置，XI质量1.4、后九纪元1.2，普通主线没有挑战奖励，自动购买与自动对角化开启，阶段切换按实际门槛执行。XIX在I0墙前正常关闭AC；关闭后如果本纪元第六项尚未解锁，就在预算足够时正常指定购买，再恢复固定顺序自动购买。它是可复现的操作策略，不表示全局最短时间。\n\n| 纪元 | 原生研究耗时（小时） | 代表质量 | 离开时研究级数 |\n| --- | ---: | ---: | --- |\n${low.firstRoute.stages.map(r=>'| '+roman[r.era]+' | '+r.hours.toFixed(6)+' | '+r.quality.toFixed(2)+' | '+r.upgrades.join(' / ')+' |').join('\n')}\n\n整段累计${(low.firstRoute.stageSumSeconds/3600).toFixed(6)}小时。这份时间不包括从I到X，也不包括人工阅读与摆出240题的现实操作时间，不能命名为“新档全游戏通关时长”。它展示的只是已经提供全星与代表设计后，XI→XX的研究推进、购买与门槛所需时间。\n\n现有xi-balance与late-balance测试元数据另外保留了辅助、普通和熟练档位。那些档位的星数、质量和研究时机与本表不相同；本节把它们标为既有元数据，并记录文件SHA-256，没有把旧测试结果重新贴成本次实测。比较时应先对齐星级、蓝图质量、遗产点和确定性策略。\n\n### 如何自己复核这组结果\n\n先备份真实进度，另开隔离环境再导入checkpoint。查看累计归一、太一、当前纪元、当前轮元公理、carry、720星和十张代表是否与表相符。原生导入会补齐某些旧存档的零库存字段；周期比较采用这种规范化后的持久表示，避免把长度不同但全零的库存数组误判成新的玩法状态。\n\n想继续观察，先确认完整轮回自动化已开、工坊仍无额外规则，随后让原生内核运行一个短段，核对它是否在当前纪元继续前进。不要导入后又开启新的挑战或改掉carry，却仍认为自己在复核同一份基线。改变策略当然可以，只是此时应该建立新的记录。\n\n所有原始数据、原生HT5、哈希、逐事件脚本和周期证明JSON都保留在simulation-p2目录。原始一天报告记录真实墙钟耗时；long-horizons记录周期与各远期checkpoint；low-progress-and-route记录首轮与低遗产对照；native-versus-cycle-day保留浮点差异。它们让读者能区分已执行的原生动作、由相同状态严格重复得到的整周期，以及浮点表示的有限误差。\n`;
fs.writeFileSync(W+'/simulation-p2.md',md);console.log(JSON.stringify({characters:md.length,routeHours:low.firstRoute.stageSumSeconds/3600,checkpoints:high.rows.length+low.rows.length+1}));
